declare(strict_types=1);require_once __DIR__.'/config/ai_analytics.php';
$error=null;$success=null;$rows=[];$metrics=[];$publishedCount=0;$days=max(7,min(365,(int)($_GET['days']??30)));$csrf='';
try{$pdo=role_portal_db();role_portal_ensure($pdo);aia_ensure($pdo);security_step17_session_start();$user=security_step17_session_user($pdo,true);if(!$user){header('Location: ../login.php');exit;}if((string)($user['role_code']??'')!=='admin'){header('Location: access_denied.php');exit;}$orgId=pscms_org_id($pdo);$csrf=security_step17_csrf();
 if($_SERVER['REQUEST_METHOD']==='POST'){security_step17_verify_csrf((string)($_POST['csrf']??''));$id=(int)($_POST['question_id']??0);$status=(string)($_POST['status']??'open');$note=trim((string)($_POST['resolution_note']??''));$answer=trim((string)($_POST['verified_answer']??''));$category=substr(trim((string)($_POST['category']??'General')),0,80)?:'General';if(!in_array($status,['open','reviewing','resolved','ignored'],true))throw new RuntimeException('Invalid status.');if($answer!==''&&mb_strlen($answer)<10)throw new RuntimeException('Verified answer must be meaningful.');if($answer!==''){$q=$pdo->prepare("SELECT question_text FROM public_ai_unanswered WHERE id=? AND organization_id=?");$q->execute([$id,$orgId]);$question=(string)$q->fetchColumn();if($question==='')throw new RuntimeException('Question was not found.');$s=$pdo->prepare("INSERT INTO public_ai_verified_answers(organization_id,source_question_id,question_text,verified_answer,category,status,created_by,updated_by) VALUES(?,?,?,?,?,'published',?,?) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text),verified_answer=VALUES(verified_answer),category=VALUES(category),status='published',updated_by=VALUES(updated_by),updated_at=NOW()");$s->execute([$orgId,$id,$question,$answer,$category,(int)$user['id'],(int)$user['id']]);$status='resolved';$note=$note?:'Published to verified AI knowledge.';}$s=$pdo->prepare("UPDATE public_ai_unanswered SET status=?,resolution_note=?,resolved_by=?,resolved_at=? WHERE id=? AND organization_id=?");$s->execute([$status,$note?:null,$status==='resolved'?(int)$user['id']:null,$status==='resolved'?date('Y-m-d H:i:s'):null,$id,$orgId]);security_step17_audit($pdo,(int)$user['id'],'ai_unanswered_updated','public_ai_unanswered',$id,['status'=>$status,'knowledge_published'=>$answer!=='']);$success=$answer!==''?'Verified answer published to the AI knowledge feed.':'Question status updated.';}
 $metrics=aia_metrics($pdo,$orgId,$days);$publishedCount=count(aia_verified_answers($pdo,$orgId));$s=$pdo->prepare("SELECT u.*,v.verified_answer,v.category FROM public_ai_unanswered u LEFT JOIN public_ai_verified_answers v ON v.organization_id=u.organization_id AND v.source_question_id=u.id WHERE u.organization_id=? AND u.created_at>=? ORDER BY FIELD(u.status,'open','reviewing','resolved','ignored'),u.created_at DESC LIMIT 100");$s->execute([$orgId,date('Y-m-d H:i:s',time()-86400*$days)]);$rows=$s->fetchAll();
}catch(Throwable $e){$error=$e->getMessage();}
